// aim.cpp — in-engine aim assist.
//
// Projects entity head positions to screen space with the camera's
// view-projection matrix, picks the target nearest the crosshair inside a
// screen-space cone (default 240px radius), and returns a frame-rate
// independent, smoothed crosshair delta toward it.
//
// Runs on the game's own entity list and camera; the caller decides when
// to apply it (e.g. only for controller input, only while ADS, etc.).

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <functional>
#include <optional>
#include <vector>

namespace aim {

struct Vec2 { float x = 0.f, y = 0.f; };
struct Vec3 { float x = 0.f, y = 0.f, z = 0.f; };

// Row-major: clip = m * [x y z 1]^T
struct Mat4 { float m[4][4]; };

struct Entity {
    uint32_t id = 0;
    Vec3     head;          // world-space head position
    bool     alive = true;
    bool     hostile = true;
};

struct Config {
    float coneRadiusPx = 240.f;  // max screen distance from crosshair
    float smoothing    = 8.f;    // convergence rate (1/s); higher = snappier
    float strength     = 1.f;    // 0..1 overall scale
    float maxStepPx    = 40.f;   // per-frame clamp on delta magnitude
    float stickyBonus  = 0.75f;  // locked target's distance is scaled by this
};

struct State {
    std::optional<uint32_t> lockedId;
};

struct Viewport {
    float width  = 0.f;
    float height = 0.f;
};

// Optional line-of-sight test supplied by the game (raycast etc.).
using VisibilityFn = std::function<bool(const Entity&)>;

// World -> screen pixels. Returns nullopt if the point is behind the camera
// or outside the clip volume.
std::optional<Vec2> worldToScreen(const Vec3& p, const Mat4& vp, const Viewport& view)
{
    const auto& m = vp.m;
    const float cx = m[0][0]*p.x + m[0][1]*p.y + m[0][2]*p.z + m[0][3];
    const float cy = m[1][0]*p.x + m[1][1]*p.y + m[1][2]*p.z + m[1][3];
    const float cz = m[2][0]*p.x + m[2][1]*p.y + m[2][2]*p.z + m[2][3];
    const float cw = m[3][0]*p.x + m[3][1]*p.y + m[3][2]*p.z + m[3][3];

    if (cw <= 1e-4f) return std::nullopt;            // behind camera

    const float nx = cx / cw;
    const float ny = cy / cw;
    const float nz = cz / cw;
    if (nx < -1.f || nx > 1.f || ny < -1.f || ny > 1.f || nz < -1.f || nz > 1.f)
        return std::nullopt;                          // off-screen / clipped

    return Vec2{
        (nx * 0.5f + 0.5f) * view.width,
        (1.f - (ny * 0.5f + 0.5f)) * view.height      // screen y grows downward
    };
}

namespace {

struct Candidate {
    uint32_t id;
    Vec2     offset;   // screen position minus crosshair
    float    score;    // lower is better
};

std::optional<Candidate> selectTarget(const std::vector<Entity>& entities,
                                      const Mat4& viewProj,
                                      const Viewport& view,
                                      const Config& cfg,
                                      const State& state,
                                      const VisibilityFn& visible)
{
    const Vec2 center{ view.width * 0.5f, view.height * 0.5f };
    const float coneSq = cfg.coneRadiusPx * cfg.coneRadiusPx;

    std::optional<Candidate> best;
    for (const Entity& e : entities) {
        if (!e.alive || !e.hostile) continue;

        auto screen = worldToScreen(e.head, viewProj, view);
        if (!screen) continue;

        const Vec2 off{ screen->x - center.x, screen->y - center.y };
        const float distSq = off.x * off.x + off.y * off.y;
        if (distSq > coneSq) continue;

        if (visible && !visible(e)) continue;

        float score = std::sqrt(distSq);
        if (state.lockedId && *state.lockedId == e.id)
            score *= cfg.stickyBonus;                 // hysteresis to avoid flicker

        if (!best || score < best->score)
            best = Candidate{ e.id, off, score };
    }
    return best;
}

} // namespace

// Returns the crosshair delta (pixels) to apply this frame. Zero if no
// target is inside the cone. `dt` is frame time in seconds.
Vec2 computeDelta(const std::vector<Entity>& entities,
                  const Mat4& viewProj,
                  const Viewport& view,
                  const Config& cfg,
                  State& state,
                  float dt,
                  const VisibilityFn& visible = {})
{
    if (view.width <= 0.f || view.height <= 0.f || dt <= 0.f || cfg.strength <= 0.f) {
        state.lockedId.reset();
        return {};
    }

    auto target = selectTarget(entities, viewProj, view, cfg, state, visible);
    if (!target) {
        state.lockedId.reset();
        return {};
    }
    state.lockedId = target->id;

    // Exponential smoothing: same convergence feel at any frame rate.
    const float alpha = 1.f - std::exp(-cfg.smoothing * dt);
    const float s = alpha * std::clamp(cfg.strength, 0.f, 1.f);

    Vec2 delta{ target->offset.x * s, target->offset.y * s };

    const float mag = std::sqrt(delta.x * delta.x + delta.y * delta.y);
    if (mag > cfg.maxStepPx && mag > 0.f) {
        const float k = cfg.maxStepPx / mag;
        delta.x *= k;
        delta.y *= k;
    }
    return delta;
}

} // namespace aim
